from collections import Counter
from functools import lru_cache

def min_subsegment_cost(n, k, a):
    @lru_cache(maxsize=None)
    def min_cost(i, j):
        if j == i + 1:  # base case
            return 0
        min_cost = float('inf')
        for start in range(i, j):
            end = start + (i - start) // 2
            left, right = Counter(a[start:end+1]), Counter(a[start:j+1]), Counter(a[start-1:start])
            for m, n in left.items():
                if n > 1:
                    left[m] -= 2
                for k, l in right.items():
                    if l > 1:
                        right[k] -= 2
                    if k == m:
                        min_cost = min(min_cost, (i - start) * 2 + m * 2 + sum(m) + sum((m-k-1) for k in right) + ((n+m-1) * 2 - sum(right)) + (j - start - m - n) * 2 + sum((n+k-1) for k in left) - sum(m) - sum(l - 1))
        return min_cost

    return min_cost(0, n)[n]

# Example usage
