# Helper function to perform modular exponentiation
def pow(k):
    temp = 1
    while k:
        if k % 2:
            temp = temp * x % mod
        x = x * x % mod
        k //= 2
    return temp

@cache
def catalan(n):
    def catalan_recursive(n):
        if n == 0 or n == 1:
            return 1
        if n % 2:
            return catalan_recursive(n - 1) * (2 * n - 1) % mod
        else:
            return catalan_recursive(n - 1) * (n // 2) % mod
    return catalan_recursive(n)

