class PowerTree:
    def __init__(self):
        self.tree = {1: 1}
        self.mod = 10**9 + 7
        self.height = 1

    def add(self, p, v):
        nonlocal height
        new_id = self.height + 1
        self.tree[new_id] = v
        while new_id != p:
            self.tree[new_id] = (self.tree[new_id] * self.tree[p] - v + self.tree[p]) % self.mod
            p, new_id = p - 1, new_id - 1
        self.tree[new_id] = v * self.tree[new_id] % self.mod
        self.height = height = self.height + 1

    def query(self, u):
        res = 0
        while u != 1:
            res = (res + self.tree[u] * self.height % self.mod)
            u -= 1
        return res % self.mod


