def c(x, y, n, mod):
    return (power(factorial(x), mod-2, mod) * power(factorial(n-x), mod-2, mod) * power((mod+power((mod-1), (x-y), mod))) % MOD * power(factorial(y), modular_inv(power(mod, y-1), mod), mod)) % MOD

def factorial(n, mod):
    ans = 1
    for i in range(n):
        ans = (ans*i) % mod
    return ans

def modular_inv(a, m):
    return power(a, m-2, m)

