from functools import cache
from math import pow

@cache
def calculate_modular_exponential(base, exponent, mod):
    """Calculate base^exponent % mod using quick exponentiation and modulo"""
    if exponent == 0:
        return 1
    elif exponent == 1:
        return base % mod
    if exponent % 2 == 0:
        half_power = calculate_modular_exponential(base, exponent // 2, mod)
        return (half_power * half_power) % mod
    else:
        half_power = calculate_modular_exponential(base, (exponent - 1) // 2, mod)
        return (base * half_power * half_power) % mod

def solve(word_length, cell_sequences):
    n = cell_sequences[0]
    mod = 10**9 + 7
    position = [False] * (2*n)
    for i, cell_sequence in enumerate(cell_sequences[1:]):
        for _ in range(n * 2):
