def remove_walls(plan):
    n = len(plan)
    m = len(plan[0])
    trees = {}
    dx = [0, 1, 0, -1]
    dy = [1, 0, -1, 0]
    for i in range(n):
        for j in range(m):
            if plan[i][j] == '*':
                for k in range(4):
                    x = i + dx[k]
                    y = j + dy[k]
                    if 0 <= x < n and 0 <= y < m and plan[x][y] == '.':
                        if (x,y) in trees:
                            continue
                        tree = [(x,y)]
                        queue = [(x,y)]
                        used = [0]

                        while queue:
                            x,y = queue.pop(0)
                            for k in range(4):
                                nx = x + dx[k]
                                ny = y + dy[k]
                                if 0 <= nx < n and 0 <= ny < m and used[abs(plan[x][y] - plan[nx][ny])] < 2:
                                    if plan[nx][ny] == '.':
                                        tree.append((nx,ny))
                                        queue.append((nx,ny))
                                        used[abs(plan[x][y] - plan[nx][ny])] += 1
                        trees[tuple(sorted(tree))] = True

    total_removed = 0
    indices = []
    for key in sorted(trees.keys()):
        if len(key) != len(set(key)) or (ord(key[0]) >= ord('a') or ord(key[0]) <= ord('z')):
            total_removed -= 1
        else:
            indices.append(key)
            total_removed += 1

    wall_number = n * m - total_removed
    plan = [list(row) for row in plan]
    for i in range(n):
        for j in range(m):
            if plan[i][j] == '*':
                if (i,j) in indices:
                    plan[i][j] = '.'
            elif plan[i][j] == '.':
                if i < wall_number:
                    plan[i][j] = '*'
                elif j < wall_number:
                    plan[i][j] = '*'

    return plan


