        if is_palindrome("".join(arrays[r][c] for r in range(row, min(row + n - col * 2 + 1, row + 50)) for c in range(col, min(col + 50, col + n - row * 2 + 1)))) and is_palindrome("".join([arrays[r][c] for r in range(min(row + n - col * 2 + 1, row + 50), row + 1)]) if col else [""]), row, col):
