def find_max_beads(n, beads):
    seen = [False] * 26
    beads.sort(reverse=True)
    for i in range(n):
        beads[i] -= 'a'.upper().encode('ascii', 'ignore')
        if beads[i] >= 2: 
            return 1
        seen[beads[i]] = True
    for i, count in enumerate(beads[1:], 1):
        if seen[ord(i.lower()) - 97] and count >= 2:
            return 1
    return 0

def solution(n, beads):
    max_beads = 0
    for cut in range(n, 0, -1):
        if is_palindrome(''.join('a' * count for count in beads if count > cut)):
            max_beads = cut
            break
    return max_beads, 'a' * beads.count(0) + ''.join('a' * count for count in beads if count > max_beads)

def print_necklace(n, beads):
    print(max_beads)
    necklace = ['b'] * n
    for color, count in sorted(enumerate(beads[:-max_beads], 1), key=lambda x: x[1], reverse=True):
        beads[color - 1] -= 1
        necklace[color - 1] = 'a' * count
    print(''.join(necklace).replace('a', ''))
