import sys

def load_file(name):
    with open(name, 'r') as file:
        return file.read()

def save_file(name, data):
    with open(name, 'w') as file:
        return file.write(data)

def parse_data(data):
    n, m = map(int, data.readline().split())
    adjacency_list = {}
    for i in range(n):
        row = data.readline()
        adjacency_list[i] = [None] * m
        for j in range(m):
            if row[j] == '*':
                adjacency_list[i][j] = j
            elif row[j] == '.':
                adjacency_list[i][j] = -1
    return n, m, adjacency_list

def find_path(x, y, adjacency_list, visited):
    if adjacency_list[x][y] == None:
        return True
    if visited[x][y] == -1:
        return False
    visited[x][y] = -1
    return find_path(adjacency_list[x][y], adjacency_list[x][y], adjacency_list, visited) or find_path(adjacency_list[x][y], y, adjacency_list, visited)

def remove_walls(n, m, adjacency_list):
    rooms = []
    for i in range(n):
        for j in range(m):
            if adjacency_list[i][j] != -1:
                if not find_path(i, j, adjacency_list, [-1]):
                    rooms.append(adjacency_list[i][j])
    if len(rooms) == 1:
        return adjacency_list

    rooms.sort()
    last_room = rooms[-1]
    rooms_to_be_removed = rooms[1:]

    for i in range(n):
        for j in range(m):
            if adjacency_list[i][j] == last_room:
                adjacency_list[i][j] = rooms_to_be_removed.pop()

    return adjacency_list

def main():
    data = load_file('input.txt')
    n, m, adjacency_list = parse_data(data)
    adjacency_list = remove_walls(n, m, adjacency_list)
    output = ""
    for i in range(n):
        output += ''.join([str(j) for j in adjacency_list[i]])
        output += '\n'
    save_file('output.txt', output)

if __name__ == "__main__":
    main()
