    res = 0
    for i in range(n):
        for j in range(m):
            if is_palindrome(grid[i][j]):
                res += 1
            if i + j >= 1 and is_palindrome(tuple(grid[i - 1][j])):
                dp[i][j][grid[i - 1][j]] += 1
            if j + n - i >= 1 and is_palindrome(tuple(grid[i][j - 1])):
                dp[i][j][grid[i][j - 1]] += 1
            if i + 1 >= 1 and j + 1 >= 1 and is_palindrome(tuple(grid[i - 1][j - 1])):
                dp[i][j][grid[i - 1][j - 1]] += 1
            for key in dp[i][j]:
                for left in dp[i][j][key]:
                    swap = {'a':'b', 'b':'a', 'c':'d', 'd':'c'}
                    target = ''.join(swap.get(c, c) for c in tuple(left))
                    valid = True
                    for k, item in dp[i][j][key].items():
                        if target not in item:
                            valid = False
                            break
                    if valid:
                        res += item[key]
                        del dp[i][j][key]
    ans = 0
    for i in range(n):
        for j in range(m):
            for key, value in dp[i][j].items():
