```python
from itertools import permutations

MOD = 1000000007

def totient(n):
    result = n
    for p in primes:
        if n % p == 0:
            result //= p
            result *= p - 1
            result %= MOD
            tmp = n // p
            while tmp % p == 0:
                tmp //= p
            if tmp != 1:
                result *= pow(p, tmp-1, MOD-1)
                result %= MOD
    return result

def is_prime(n):
    if n == 2:
        return True
    if n == 1 or n & 1 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def get_primes():
    primes = [2]
    for n in range(3, 1000000+1):
        if is_prime(n):
            primes.append(n)
    return primes

def count_pairs(n, k):
    pairs = []
    for i in range(k):
        pairs += list(permutations([i, n - i - 1], 2))
    return len(pairs)

def solve(n):
    primes = get_primes()
    pairs = count_pairs(n, 2)
    sum = 0
    for i in range(n):
        perm = permutations([i] * 2)
        for p in perm:
            sum += totient(p[0]*p[1])
        sum *= 2
        sum %= MOD
    for i in range(k):
        sum = (sum - pairs[i]) * 288 % MOD
    return sum % MOD

