def is_lexicographically_smaller(s1, s2):
    if len(s2) <= 1:
        return True
    i = j = 0
    while i < len(s1) and j < len(s2) and s1[i] == s2[j]:
        i += 1
        j += 1
    if i < len(s1) or (i == len(s1) and j < len(s2)):
        return False
    return True

def find_largest_increasing_subsequence(s, n):
    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if is_lexicographically_smaller(s[j:i+1], s[i:j+1]):
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

