from fractions import Fraction

def extended_gcd(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        g, y = extended_gcd(b, a % b)
        return (g, y, (x - y * (a // b)),)

def power(x, y, p):
    """Compute (x^y) mod p"""
    res = 1
    x = x % p
    while y > 0:
        if y % 2:
            res = (res * x) % p
        y = y // 2
        x = (x*x) % p
    return res

def solve(n, k):
    if n == 1:
        return 2
    elif n == 2:
        return power(7, k, n * (10 ** 9 + 7))
    else:
        f, _, _ = extended_gcd(k, n - 1)
        ans = 1
        for i in range(1, f + 1):
            ans = ans * (1 + (n - 1) // (f * i)) % (10 ** 9 + 7)
        return ans % (10 ** 9 + 7)

