def remove_walls_to_form_rectangles(n, m, plan):
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    visited = [[False] * m for _ in range(n)]
    queue = []
    for i in range(n):
        for j in range(m):
            if plan[i][j] == '*':
                queue.append((i, j))
                visited[i][j] = True
            elif plan[i][j] == '.':
                for dx, dy in directions:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                        queue.append((nx, ny))
                        visited[nx][ny] = True

    result = [['.' for _ in range(m)] for _ in range(n)]
    seen_movement = set()

    while queue:
        x, y = queue.pop(0)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not seen_movement and not visited[nx][ny]:
                seen_movement.add((nx, ny))
                result[nx][ny] = '#'
                queue.append((nx, ny))

    return result

