from itertools import accumulate

def minimize_split_cost(arr, k):
    n = len(arr)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    prefix = [0] * (n + 1)

    # Precompute prefix sums for constant time queries
    for i in range(1, n + 1):
        prefix[i] = prefix[i - 1] + (arr[i - 1] if i > 0 else 0)

    # 2D DP: rows represent the position (in the input array) and columns represent the splits
    dp2d = [[[float('inf')] * k for _ in range(n)] for _ in range(k)]

    # Alternatively, O(N^2*K) Dynamic Programming approach (O(4*N**2) space)
    # dp2d[i][j] holds the minimum cost to split from 0 to i and ith subsegment has j segments
    for i in range(n):
        for j in range(k):
            for cost in range(1, i + 1):
                dp2d[j][i][j] = min(dp2d[j][i][j], dp[j] + dp2d[j][cost][i] + (prefix[i + 1] - prefix[cost]))
            dp2d[j][i][j] += cost # (record original segment cost for all previous subsegments)

    # Recursion with memoization (O(N**2*K) dominates)
    max_tuples, tuples_taken = list(), []
    for length in range(1, k + 1):
        for start in range(n):
            totals, taken = [], []
            for end in range(start, min(n, start + length)):
                if n - end < length - 1:
                    break
                totals.append(dp[length - 1][end] + (prefix[end + 1] - prefix[start]))
                taken.append((start, end, length, cost))
            max_tuples.append((max(totals), tuples_taken))
            tuples_taken.extend(taken)

    cost, solutions = list(), []
    for cost_ in max_tuples:
        if cost > 0:
            solutions.append([i for tc in cost_.return_tuples() for i in tc])

    return min(solutions)

def return_tuples(self):
    return self[::][(slice(None), )]

