MOD = 1_000_000_007

class PowerTree:
    def __init__(self, root_value):
        self.root_value = root_value
        self.tree = [self.root_value]

    def update(self, update_type, vertex, value):
        if update_type == 1:
            self._add_vertex(vertex, value)
        else:
            parent_value, child_value = self._get_parent_value(vertex)
            new_value = (parent_value * child_value + child_value) % MOD
            self.tree[vertex - 1] = new_value
            for p in self.get_descendants(vertex):
                self.tree[p - 1] = new_value

    def query(self, vertex):
        parent_value, child_value = self._get_parent_value(vertex)
        result = (parent_value * child_value + child_value) % MOD
        for p in self.get_descendants(vertex):
            result = (result + parent_value * self.tree[p - 1]) % MOD
        return result

    def _add_vertex(self, vertex, value):
        self.tree.append(value)
        parent = None
        for p in [v - 1 for v in self.tree]:
            if not self.tree[p]:
                self.tree[p] = value
            else:
                parent = p

    def _get_parent_value(self, vertex):
        parent = None
        for p in [v - 1 for v in self.tree]:
            if self.tree[p] and (parent is None or parent > p):
                parent = p
        return self.tree[parent], self.tree[vertex - 1]

    def get_descendants(self, vertex):
        for i in range(1, len(self.tree)):
            if self.tree[i]:
                yield i

# Example usage
