from itertools import accumulate, permutations

def mex(nums):
    num_set = set()
    for num in nums:
        num_set.add(num)
    for i in range(1, 8):
        num_set.add(i)
    return len(num_set)

def get_longest_increasing_sequence(s, max_count):
    n = len(s)
    count = [0] * 8
    start = [0] * n
    cur_prefix = [0] * n
    for i in range(n):
        cur_prefix[i] = 1 if s[i] < 8 else 2
    cur_count = accumulate(cur_prefix)
    while all(x < n for x in cur_prefix):
        for i in range(n):
            start[i] = cur_prefix.index(max(cur_prefix))
        count[cur_prefix[start[n - 1]]] += 1
        for i in range(n - 2, -1, -1):
            cur_prefix[i] += 1
            if cur_prefix[i] < 8:
                start[i] = cur_prefix.index(max(cur_prefix))
        cur_count[next(accumulate(count))] += n - i - 1
        for i in range(n - 2, -1, -1):
            cur_count[next(accumulate(count))] -= 1
            if count[next(cur_prefix[i])] == max_count:
                break
    return sum(count) + cur_count[-1] * max_count

def main():
