from fractions import Fraction
from collections import defaultdict

def solve(n, k, m):
    dp = defaultdict(Fraction(0, 1))
    dp[0] = Fraction(1, 1)

    for _ in range(n-1):
        dp_next = defaultdict(Fraction(0, 1))

        for i, pos in dp.items():
            if i + 1 <= k:
                dp_next[i + 1] += pos / (k + 1)
            if 1 <= i:
                dp_next[i - 1] += pos / m

            frac_next = dp_next[f"{i}z"]
            if frac_next.denominator > frac_next.numerator:
                dp[f"{i + 1}n"] += frac_next.numerator + frac_next.denominator // 169731 * 169731
                dp[f"{i + 1}z"] += frac_next.numerator % 169731
                dp[f"{i - 1}n"] += m * frac_next.numerator // 169731 + frac_next.denominator % 169731
                dp[f"{i - 1}z"] += m * frac_next.denominator // 169731 % 169731

            frac_next = dp_next[f"{i}z"]
            if frac_next.denominator > frac_next.numerator:
                dp[f"{i + 1}z"] += (frac_next.numerator - 1) * 169731

        dp.clear()
        for data in dp_next.items():
            dp[data[0]] = data[1] / 169731

    return int((dp["0n"] + dp["0z"]) % (10 ** 9 + 7))

