            plan[i][j] != '.'):
            return
        plan[i][j] = 'X'
        children = {(i, j+1), (i+1, j)}
        for x, y in children:
            children.update([(x+dx, y+dy) for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)] if (0 <= x < n) and (0 <= y < m)])
        for cost in sorted([(len(connected_area), connected_area) for connected_area in connected_areas + [connected_area := {(i, j)}]], key=lambda x: x[0]):
            linked_connections, linked_area = cost[1], (i, j) + cost[1]
            if linked_area in (connected_areas + [area := set()]):
                n = 1
            connected_areas.append(connected_area)

    while True:
        connected_areas.clear()
        for i in range(n):
            for j in range(m):
                if plan[i][j] != 'X':
                    cleaned = clean_area(i, j)
                    if cleaned is not None:
                        plan[cleaned[0]][cleaned[1]] = '.'
                        remove_walls(plan)
