import sys

def max_beautiful_cuts(colors):
    n = len(colors)
    max_cuts = 0
    for cuts in range(n, -1, -1):
        if n - cuts * n % 2 >= cuts:
            max_cuts = cuts
    return max_cuts

def generate_necklace(colors):
    n = len(colors)
    necklace = ['a'] * n
    last_color = None
    i = 0
    while i < n:
        next_color = None
        found = False
        for color in range(ord('a'), ord('z') + 1):
            count = colors[color - ord('a')]
            if i + count <= n:
                multi = count // cuts
                remainder = count % cuts
                start = n - i - remainder
                for j in range(cuts):
                    start += remainder + j
                    if start > n:
                        start -= n
                    if necklace[start] != 'a' and necklace[start] != chr(color):
                        necklace[start] = chr(color)
                        if next_color is None:
                            next_color = chr(color)
                        else:
                            next_color = None
                        found = True
                        break
                if found:
                    i += n - cuts
                    break
            if i + multi >= n:
                break
            start = i + mult * n
            if necklace[start] != 'a' and necklace[start] != chr(color):
                necklace[start] = chr(color)
                found = True
                break
            if i + multi >= n:
                break
        if next_color is None:
            break
        i += 1
    return ''.join(necklace)

