import sys
from collections import deque

def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rank[rootX] < rank[rootY]:
        parent[rootX] = rootY
    elif rank[rootX] > rank[rootY]:
        parent[rootY] = rootX
    else:
        parent[rootY] = rootX
        rank[rootX] += 1

def kruskal(edges, m):
    edges.sort()
    res = [0]*len(edges)
    parent = [i for i in range(n + 1)]
    rank = [0] * (n + 1)
    for i in range(m):
        x, y, weight = edges[i]
        if find(parent, x) != find(parent, y):
            union(parent, rank, x, y)
            res[i] = weight
            # Ensure all edges are unique
            res[n] = -1
    return res

def main():
    n, m = map(int, sys.stdin.readline().split())
    edges = []
    for _ in range(m):
        u, v, weight = map(int, sys.stdin.readline().split())
        edges.append((u, v, weight))

    minimum_spanning_tree = kruskal(edges, m)
    for i in range(m):
        print(minimum_spanning_tree[i] if i < n else "-1")
    return

if __name__ == "__main__":
    main()
